G1=$(group 'fwshift-addresses' 'FWShift: for the interfaces of 0.0.0.0-10.9.255.255 10.11.0.0-10.19.255.255 10.20.1.0-10.30.0.255 10.30.2.0-192.0.2.52 192.0.2.55-198.51.100.0 198.51.100.2-203.0.113.9 ...') || exit 1
